const setFieldIfUnchanged = `-- name: SetFieldIfUnchanged :one
UPDATE listings
SET title = CASE WHEN $1::text = 'title' THEN $2::text ELSE title END,
    bullet_1 = CASE WHEN $1::text = 'bullet_1' THEN $2::text ELSE bullet_1 END,
    bullet_2 = CASE WHEN $1::text = 'bullet_2' THEN $2::text ELSE bullet_2 END,
    bullet_3 = CASE WHEN $1::text = 'bullet_3' THEN $2::text ELSE bullet_3 END,
    bullet_4 = CASE WHEN $1::text = 'bullet_4' THEN $2::text ELSE bullet_4 END,
    bullet_5 = CASE WHEN $1::text = 'bullet_5' THEN $2::text ELSE bullet_5 END,
    description = CASE WHEN $1::text = 'description' THEN $2::text ELSE description END,
    version = version + 1, rule_status = 'failing', updated_at = now()
WHERE id = $3 AND status = 'generated'
  AND CASE $1::text
        WHEN 'title' THEN title WHEN 'bullet_1' THEN bullet_1 WHEN 'bullet_2' THEN bullet_2
        WHEN 'bullet_3' THEN bullet_3 WHEN 'bullet_4' THEN bullet_4 WHEN 'bullet_5' THEN bullet_5
        WHEN 'description' THEN description END = $4::text
RETURNING version
`

type SetFieldIfUnchangedParams struct {
	Field     string `json:"field"`
	Value     string `json:"value"`
	ID        int64  `json:"id"`
	BaseValue string `json:"base_value"`
}

func (q *Queries) SetFieldIfUnchanged(ctx context.Context, arg SetFieldIfUnchangedParams) (int32, error) {
	row := q.db.QueryRow(ctx, setFieldIfUnchanged,
		arg.Field,
		arg.Value,
		arg.ID,
		arg.BaseValue,
	)
	var version int32
	err := row.Scan(&version)
	return version, err
}

