const writeGenerated = `-- name: WriteGenerated :one

UPDATE listings
SET status = 'generated', failure_reason = NULL, version = version + 1,
    title = $2, bullet_1 = $3, bullet_2 = $4, bullet_3 = $5, bullet_4 = $6, bullet_5 = $7,
    description = $8, rule_status = 'failing', updated_at = now()
WHERE id = $1
RETURNING version
`

type WriteGeneratedParams struct {
	ID          int64       `json:"id"`
	Title       pgtype.Text `json:"title"`
	Bullet1     pgtype.Text `json:"bullet_1"`
	Bullet2     pgtype.Text `json:"bullet_2"`
	Bullet3     pgtype.Text `json:"bullet_3"`
	Bullet4     pgtype.Text `json:"bullet_4"`
	Bullet5     pgtype.Text `json:"bullet_5"`
	Description pgtype.Text `json:"description"`
}

// A text or attribute change sets rule_status to failing as a placeholder:
// a generated listing is never unchecked (chk_listings_generated_checked), and
// Revalidate sets the real status in the same transaction. A listing of a
// switched-off channel stays failing, so it cannot be approved (D8).
func (q *Queries) WriteGenerated(ctx context.Context, arg WriteGeneratedParams) (int32, error) {
	row := q.db.QueryRow(ctx, writeGenerated,
		arg.ID,
		arg.Title,
		arg.Bullet1,
		arg.Bullet2,
		arg.Bullet3,
		arg.Bullet4,
		arg.Bullet5,
		arg.Description,
	)
	var version int32
	err := row.Scan(&version)
	return version, err
}
